#include "optimizer.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static void show(const Plan *p){int i;puts("ID  Destination Weight Priority Value");for(i=0;i<p->count&&i<30;i++){Order o=p->orders[i];printf("%-3d %-11d %-6d %-8d %d\n",o.id,o.destination,o.weight,o.priority,o.value);}if(p->count>30)printf("... %d more orders\n",p->count-30);}
int main(int argc,char **argv){Plan *p=malloc(sizeof(Plan));int c,id,d,w,pr,v,a,b,cost;if(!p)return 1;scenario(p,0);if(argc>1){if(!strcmp(argv[1],"--benchmark")){benchmark();free(p);return 0;}if(!strcmp(argv[1],"--test")){int ok=run_tests();free(p);return ok?0:1;}}for(;;){puts("\n=== E-COMMERCE DELIVERY OPTIMIZER ===\n1 Add order\n2 Display orders\n3 Compare algorithms / report\n4 Normal scenario\n5 Capacity shock\n6 Large stress\n7 Adversarial scenario\n8 Benchmark all\n9 Run tests\n10 Change capacity\n11 Add road\n0 Exit");printf("Choice: ");if(scanf("%d",&c)!=1)break;switch(c){case 0:free(p);return 0;case 1:puts("ID Destination Weight Priority Value:");if(scanf("%d%d%d%d%d",&id,&d,&w,&pr,&v)!=5)goto bad;{Order o={id,d,w,pr,v};puts(order_add(p,o)?"Added":"Invalid/duplicate order");}break;case 2:show(p);break;case 3:report(p);break;case 4:puts("\n===== NORMAL SCENARIO =====");scenario(p,0);report(p);break;case 5:puts("\n===== CAPACITY SHOCK SCENARIO =====");scenario(p,1);report(p);break;case 6:puts("\n===== LARGE STRESS SCENARIO =====");scenario(p,2);report(p);break;case 7:puts("\n===== ADVERSARIAL SCENARIO =====");scenario(p,3);report(p);break;case 8:benchmark();break;case 9:run_tests();break;case 10:puts("New capacity:");if(scanf("%d",&c)!=1)goto bad;if(c>=0&&c<=MAX_CAP)p->capacity=c;else puts("Invalid capacity");break;case 11:puts("Source Destination Cost:");if(scanf("%d%d%d",&a,&b,&cost)!=3)goto bad;puts(road_add(&p->network,a,b,cost)?"Road added":"Invalid road");break;default:puts("Invalid choice");}}bad:puts("Invalid input; exiting");free(p);return 1;}
